add-to-array-form-of-integer:
class Solution:
    def addToArrayForm(self, num: List[int], k: int) -> List[int]:
        num = [str(x) for x in num]
        n = int(''.join(num)) + k
        return [int(d) for d in str(n)]

arrange-coins:
import math
class Solution:
    def arrangeCoins(self, n: int) -> int:
        return int((math.isqrt(8 * n + 1) - 1) // 2)

construct-rectangle:
class Solution:
    def constructRectangle(self, area: int) -> List[int]:
        w = int(area ** 0.5)
        while area % w: w -= 1
        return [area // w, w]

dominant-index:
class Solution:
    def dominantIndex(self, nums: List[int]) -> int:
        m = max(nums)
        return nums.index(m) if all(m >= 2 * n for n in nums if n != m) else -1

one-bit-and-2-bit-characters:
class Solution:
    def isOneBitCharacter(self, bits: List[int]) -> bool:
        i = 0
        while i < len(bits) - 1:
            i += 2 if bits[i] else 1
        return i == len(bits) - 1
